SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM a.admittime) = 2015 AND EXTRACT(YEAR FROM a.dischtime) = 2016 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 45 AND 55 AND d.icd_code IN ('440', '448') AND e.drug_type IN ('Insulin', 'Oral antidiabetic') AND h.intime BETWEEN 0 AND 12 THEN e.drug_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.drug_id), 0) AS proportion FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN emar e ON a.subject_id = e.subject_id JOIN pharmacy ph ON e.pharmacy_id = ph.pharmacy_id JOIN icustays h ON a.stay_id = h.stay_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id;